76	pub fn coverage(spec: &DepSpec, new: &Version) -> Result<Coverage, GrammarMismatch> {
77	    match spec {
78	        DepSpec::Exact(v) => {
79	            if v == new {
80	                Ok(Coverage::Covers)
81	            } else {
82	                Ok(Coverage::DoesNotCover)
83	            }
84	        }
85	        DepSpec::CargoBare(v) => {
86	            if caret_covers(v, new)? {
87	                Ok(Coverage::Covers)
88	            } else {
89	                Ok(Coverage::DoesNotCover)
90	            }
91	        }
92	        DepSpec::Range(req, _) => {
93	            if req.matches(new)? {
94	                Ok(Coverage::Covers)
95	            } else {
96	                Ok(Coverage::DoesNotCover)
97	            }
98	        }
99	        DepSpec::Workspace(_) => Ok(Coverage::Covers),
100	        DepSpec::Catalog(_) | DepSpec::Opaque(_) => Ok(Coverage::Unknown),
101	    }
102	}
