104	pub(crate) fn caret_covers(cur: &Version, new: &Version) -> Result<bool, GrammarMismatch> {
105	    let cmp = Version::compare(new, cur)?;
106	    if cmp.is_lt() {
107	        return Ok(false);
108	    }
109	    // Pre-release versions are never covered by a caret range: ^1.2.3 must not
110	    // satisfy 1.9.0-alpha.1 even though 1.9.0-alpha.1 > 1.2.3 and they share
111	    // the same major. Caret ranges cover stable releases within the allowed
112	    // major/minor bounds only; a pre-release of an in-range stable version is
113	    // not itself a stable release and must not be treated as covered.
114	    if new.is_prerelease() {
115	        return Ok(false);
116	    }
117	    let cur_maj = cur.major().unwrap_or(0);
118	    let cur_min = cur.minor().unwrap_or(0);
119	    let new_maj = new.major().unwrap_or(0);
120	    let new_min = new.minor().unwrap_or(0);
121	
122	    if cur_maj > 0 {
123	        Ok(new_maj == cur_maj)
124	    } else if cur_min > 0 {
125	        Ok(new_maj == 0 && new_min == cur_min)
126	    } else {
127	        Ok(new == cur)
128	    }
129	}
