405	fn bump_target<D: DependencyResolver>(
406	    id: &PackageId,
407	    sev: Severity,
408	    input: &CascadeInput<'_, D>,
409	) -> Result<Version, GraphError> {
410	    let base = input.base.get(id).cloned().ok_or_else(|| {
411	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
412	            path: PathBuf::from(id.name()),
413	            field: "version",
414	        })
415	    })?;
416	    let versioning: &dyn callisto_format::Versioning = match base.grammar() {
417	        callisto_model::VersionGrammar::Pep440 => &callisto_format::Pep440Versioning,
418	        _ => &callisto_format::SemVerVersioning,
419	    };
420	
421	    if let Some(pre) = input.pre {
422	        if pre.mode == callisto_format::PreMode::Pre {
423	            let pinned_base = pre.initial_versions.get(id.name()).unwrap_or(&base);
424	            versioning
425	                .bump_prerelease(pinned_base, sev, &pre.tag, &base)
426	                .map_err(GraphError::Bump)
427	        } else {
428	            // PreMode::Exit: finalize the current pre-release to a stable version.
429	            // Bumping the on-disk pre-release version (e.g. "1.0.0-alpha.2") with
430	            // any severity that matches the pre-release target strips the tag and
431	            // produces the stable version (e.g. "1.0.0").
432	            versioning.bump(&base, sev).map_err(GraphError::Bump)
433	        }
434	    } else {
435	        versioning.bump(&base, sev).map_err(GraphError::Bump)
436	    }
437	}
