439	#[allow(clippy::too_many_arguments)]
440	fn raise<D: DependencyResolver>(
441	    pkg: &PackageId,
442	    sev: Severity,
443	    decision: &CascadeDecision,
444	    via: &PackageId,
445	    edge: &DepEdge,
446	    dependency_to: &Version,
447	    out: &mut CascadeOutcome,
448	    groups: &GroupTable,
449	    worklist: &mut BTreeSet<PackageId>,
450	    input: &CascadeInput<'_, D>,
451	) -> Result<bool, GraphError> {
452	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
453	    if sev <= cur_sev {
454	        return Ok(false);
455	    }
456	
457	    out.severities.insert(pkg.clone(), sev);
458	
459	    let new_reason = if decision.escalated {
460	        BumpReason::PeerEscalation {
461	            via: via.clone(),
462	            spec: edge.spec.render(),
463	        }
464	    } else {
465	        BumpReason::Cascade {
466	            via: via.clone(),
467	            dep_kind: edge.kind,
468	            spec: edge.spec.render(),
469	            dependency_to: dependency_to.clone(),
470	        }
471	    };
472	    out.reasons.insert(pkg.clone(), new_reason);
473	
474	    if let Some(ref gov) = decision.governed_by {
475	        out.governed_by.insert(pkg.clone(), gov.clone());
476	    }
477	
478	    let new_t = bump_target(pkg, sev, input)?;
479	    out.targets.insert(pkg.clone(), new_t);
480	    worklist.insert(pkg.clone());
481	
482	    for sib in groups.fixed_siblings(pkg) {
483	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
484	        if sev > sib_sev {
485	            out.severities.insert(sib.clone(), sev);
486	            out.reasons.insert(
487	                sib.clone(),
488	                BumpReason::FixedGroupUnion {
489	                    group: groups.fixed_group_of(pkg).unwrap().name.clone(),
490	                },
491	            );
492	            let sib_t = bump_target(sib, sev, input)?;
493	            out.targets.insert(sib.clone(), sib_t);
494	            worklist.insert(sib.clone());
495	        }
496	    }
497	
498	    Ok(true)
499	}
