531	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
532	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm {
533	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
534	    }
535	
536	    if let Some(rewritten) = callisto_manifests::round_trip(eco, original, new) {
537	        RewriteOutcome::Rewritten(rewritten)
538	    } else {
539	        RewriteOutcome::LeftAlone(Diagnostic {
540	            code: DiagnosticCode::RangeNotRoundTrippable,
541	            severity: DiagnosticSeverity::Warning,
542	            message: format!(
543	                "spec `{}` could not be round-tripped toward version `{}`",
544	                original.render(),
545	                new.render()
546	            ),
547	            package: None,
548	            path: None,
549	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
550	            escalated_by: None,
551	        })
552	    }
553	}
