555	#[cfg(test)]
556	mod tests {
557	    use super::*;
558	    use callisto_model::{GroupKind, GroupName, Package, ReleaseTrigger, VersionGrammar};
559	
560	    use crate::config::{CascadeBumpSeverity, GroupDef, GroupMember};
561	
562	    /// §13 invariant 9 / §7.4 row 5 vs row 4: peer-dependency escalation to
563	    /// `Severity::Major` must only fire when the upstream (source) severity
564	    /// is non-patch (Minor or Major). A patch-severity source that leaves a
565	    /// peer spec out of range falls through to row 4 (`cfg.bump_severity`),
566	    /// not a manufactured Major bump -- `cascade_action`'s `source` parameter
567	    /// must actually gate the escalation, not just be accepted and ignored.
568	    #[test]
569	    fn cascade_action_peer_escalation_only_fires_for_non_patch_source() {
570	        let cfg = CascadeConfig {
571	            mode: CascadeMode::OutOfRange,
572	            bump_severity: CascadeBumpSeverity::Patch,
573	            peer_escalation: true,
574	            preserve_npm_ranges: false,
575	        };
576	
577	        // Patch-severity source: must NOT escalate to Major (row 4).
578	        let patch_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::Patch, &cfg);
579	        assert_eq!(
580	            patch_decision.severity,
581	            Severity::Patch,
582	            "a patch-severity upstream source must not escalate a peer dependent to Major"
583	        );
584	        assert!(
585	            !patch_decision.escalated,
586	            "a patch-severity source must not set `escalated`"
587	        );
588	        assert_eq!(
589	            patch_decision.governed_by,
590	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
591	            "a patch-severity source falls through to the ordinary bump_severity row"
592	        );
593	
594	        // Minor-severity source: MUST escalate to Major (row 5).
595	        let minor_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::Minor, &cfg);
596	        assert_eq!(
597	            minor_decision.severity,
598	            Severity::Major,
599	            "a non-patch (Minor) upstream source must escalate a peer dependent to Major"
600	        );
