604	        // Major-severity source: MUST also escalate to Major (row 5).
605	        let major_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::Major, &cfg);
606	        assert_eq!(major_decision.severity, Severity::Major);
