609	        // None-severity source: provably unreachable through run_cascade (every
610	        // write site into the severities map gates on `sev > Severity::None`
611	        // before inserting), but the match arm falls through to row 4 exactly
612	        // like Patch if it ever were reached -- exhaustive over the enum
613	        // rather than relying on that untested cross-function invariant.
614	        let none_decision = cascade_action(DepKind::Peer, Coverage::DoesNotCover, Severity::None, &cfg);
615	        assert_eq!(none_decision.severity, Severity::Patch);
616	        assert!(!none_decision.escalated);
617	    }
