704	    /// In-memory graph that supports arbitrary edges for cascade tests.
705	    struct TestGraph {
706	        packages: Vec<Package>,
707	        edges: Vec<DepEdge>,
708	    }
709	
710	    impl DependencyResolver for TestGraph {
711	        fn packages(&self) -> impl Iterator<Item = &Package> {
712	            self.packages.iter()
713	        }
714	
715	        fn dependencies_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
716	            // Return edges where `from == id` (id depends on the target).
717	            self.edges.iter().filter(move |e| &e.from == id)
718	        }
719	
720	        fn dependents_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
721	            // Return edges where `to == id` (i.e. the caller depends on id).
722	            self.edges.iter().filter(move |e| &e.to == id)
723	        }
724	    }
